    const active=thumbs[crewIndex],strip=$('#crew-filmstrip');if(active&&strip){const left=Math.max(0,active.offsetLeft-(strip.clientWidth-active.clientWidth)/2);strip.scrollTo({left,behavior:'smooth'});}
